/* @lc app=leetcode id=3244 lang=kotlin */ class Solution { fun shortestDistanceAfterQueries(n: Int, queries: Array<IntArray>): IntArray = IntArray(n) { it + 1 }.let { nxt -> queries.fold(n - 1 to ArrayList<Int>()) { (d, res), (u, v) -> (if (nxt[u] == -1 || nxt[u] >= v) emptyList() else generateSequence(nxt[u]) { nxt[it].takeIf { y -> y < v } }.toList().also { ch -> ch.forEach { nxt[it] = -1 } }.also { nxt[u] = v }).let { ch -> (d - ch.size).let { d2 -> d2 to res.also { it.add(d2) } } } }.second.toIntArray() } }